package com.live

import android.util.Base64

internal object JsFonts {
    private val archivo_regular = listOf(
            "",
            ""
        )
    private val bagnard = listOf(
            ""
        )
    private val bluunext_titling = listOf(
            "",
            ""
        )

    private val all: Map<String, List<String>> by lazy { mapOf("archivo_regular" to archivo_regular, "bagnard" to bagnard, "bluunext_titling" to bluunext_titling) }

    fun bytes(key: String): ByteArray? =
        all[key]?.let { Base64.decode(it.joinToString(""), Base64.DEFAULT) }
}
